// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    Recorder r;

    function setUp() public { c = new airPort(); r = new Recorder(); }

    // fuzz the from address and the recipients array length and values
    function testFuzz_property(address from, address a0, address a1, uint8 n) public {
        // make a small recipients array but allow 1 or 2 elements (wider domain)
        // bound n to 1..2 so we can reason about _tos[0] existing
        uint8 len = uint8(bound(n, 1, 2));
        address[] memory tos = new address[](len);
        tos[0] = a0;
        if (len > 1) tos[1] = a1;

        // The contract C will call transferFrom(address,address,uint256) on the provided caddress.
        // We pass our Recorder which records every call including the decoded args.

        // Call through c.transfer; it is non-payable and does not depend on msg.sender, so just call directly.
        bool ok;
        try c.transfer(from, address(r), tos, 123) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: For any non-empty tos, the reference implementation will call transferFrom for tos[0].
        // We observe Recorder to ensure it recorded at least one call and that the first recorded `to` equals tos[0].
        // This will hold for the reference, but the mutant skipping index 0 will fail when len>=1.

        // Ensure the call itself didn't revert in a way that prevents observation; the recorder's function does not revert.
        // Assert that if c returned normally (ok==true) then recorder saw at least one call and its first recorded `to` equals tos[0].
        // (This single assert reads c's observable behaviour through the Recorder contract.)
        if (ok) {
            // read recorder's recorded data
            uint256 calls = r.callCount();
            // Must have recorded at least one call and the first call's `to` must be tos[0]
            assertTrue(calls >= 1 && r.calledTos(0) == tos[0]);
        } else {
            // If transfer reverted, then mutant also may revert differently; still assert a property that holds on reference:
            // Reference never reverts in normal flow because Recorder's function does not revert, so ok should be true for reference.
            // For the purposes of the single universal assertion required by the harness, require ok == true.
            // This will pass on reference and fail on mutants that skip calling and somehow cause revert differences.
            assertTrue(ok);
        }
    }
}

// Recorder contract that exposes the exact function selector called by C: transferFrom(address,address,uint256)
contract Recorder {
    struct Call { address from; address to; uint256 v; }
    Call[] public calls;

    // matches selector bytes4(keccak256("transferFrom(address,address,uint256)"))
    function transferFrom(address from, address to, uint256 v) external returns (bool) {
        calls.push(Call({from: from, to: to, v: v}));
        return true;
    }

    // helpers for the test to read recorded data
    function callCount() external view returns (uint256) { return calls.length; }
    function calledTos(uint256 i) external view returns (address) { return calls[i].to; }
}
